<?php
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/compat.php';
$u=require_permission('roles.view');$msg='';$err='';$d=db_load();$catalog=permission_catalog();$keys=permission_keys();
$canManage=user_can($u,'roles.manage',$d);
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();
    try{
        if(!$canManage) throw new RuntimeException('บัญชีนี้ดู Permission ได้ แต่ไม่มีสิทธิ์แก้ไข');
        $action=(string)($_POST['action']??'');$uid=(int)$u['id'];
        if($action==='create_role'){
            $slug=permission_slug((string)($_POST['slug']??''));$name=trim((string)($_POST['name']??''));$desc=trim((string)($_POST['description']??''));$clone=(string)($_POST['clone_role']??'staff');
            if($slug===''||$name==='')throw new RuntimeException('กรอกชื่อ Role และ Role Key ให้ครบ');
            if(in_array($slug,['admin','staff','pr'],true))throw new RuntimeException('Role Key นี้สงวนไว้สำหรับระบบ');
            db_mutate(function($d)use($slug,$name,$desc,$clone,$u){if(isset($d['roles'][$slug]))throw new RuntimeException('Role Key ซ้ำ');$base=$d['roles'][$clone]['permissions']??[];$d['roles'][$slug]=['name'=>$name,'description'=>$desc,'builtin'=>0,'home'=>(string)($d['roles'][$clone]['home']??'dashboard.php'),'permissions'=>$base];audit_permission($d,$u,'role_created',['role'=>$slug,'clone'=>$clone]);return $d;});$msg='สร้าง Custom Role แล้ว';
        } elseif($action==='save_role'){
            $role=(string)($_POST['role']??'');$selected=array_values(array_intersect($keys,array_keys($_POST['perm']??[])));$home=(string)($_POST['home']??'dashboard.php');if(!in_array($home,['admin.php','dashboard.php','pr.php','employee-time.php','employee-calendar.php','night-ops.php','admin-tools.php'],true))$home='dashboard.php';
            db_mutate(function($d)use($role,$selected,$home,$u){if(!isset($d['roles'][$role]))throw new RuntimeException('ไม่พบ Role');$d['roles'][$role]['permissions']=array_fill_keys($selected,1);$d['roles'][$role]['home']=$home;audit_permission($d,$u,'role_permissions_saved',['role'=>$role,'count'=>count($selected)]);return $d;});$msg='บันทึก Permission ของ Role แล้ว';
        } elseif($action==='delete_role'){
            $role=(string)($_POST['role']??'');
            db_mutate(function($d)use($role,$u){if(!isset($d['roles'][$role]))throw new RuntimeException('ไม่พบ Role');if(!empty($d['roles'][$role]['builtin']))throw new RuntimeException('ลบ Built-in Role ไม่ได้');foreach($d['users'] as $x)if(($x['role']??'')===$role)throw new RuntimeException('ยังมี User ใช้ Role นี้ กรุณาย้าย Role ของ User ก่อน');unset($d['roles'][$role]);audit_permission($d,$u,'role_deleted',['role'=>$role]);return $d;});$msg='ลบ Custom Role แล้ว';
        } elseif($action==='save_user_override'){
            $target=(int)($_POST['user_id']??0);$over=[];foreach($keys as $k){$v=(string)($_POST['override'][$k]??'inherit');if($v==='allow')$over[$k]=1;elseif($v==='deny')$over[$k]=0;}
            db_mutate(function($d)use($target,$over,$u){foreach($d['users'] as &$x){if((int)$x['id']!==$target)continue;if(!empty($x['super_admin'])&&(int)$x['id']===(int)$u['id']&&isset($over['roles.manage'])&&$over['roles.manage']===0)throw new RuntimeException('Super Admin ไม่สามารถ Deny สิทธิ์จัดการ Permission ของตัวเองได้');$x['permission_overrides']=$over;audit_permission($d,$u,'user_permission_override_saved',['user_id'=>$target,'count'=>count($over)]);return $d;}unset($x);throw new RuntimeException('ไม่พบ User');});$msg='บันทึกสิทธิ์เฉพาะ User แล้ว';
        } elseif($action==='set_user_role'){
            $target=(int)($_POST['user_id']??0);$role=(string)($_POST['role']??'');
            db_mutate(function($d)use($target,$role,$u){if(!isset($d['roles'][$role]))throw new RuntimeException('Role ไม่ถูกต้อง');foreach($d['users'] as &$x){if((int)$x['id']!==$target)continue;if(!empty($x['super_admin'])&&$role!=='admin')throw new RuntimeException('ต้องถอด Super Admin ก่อนจึงจะเปลี่ยน Role ได้');$old=$x['role']??'';$x['role']=$role;audit_permission($d,$u,'user_role_changed',['user_id'=>$target,'from'=>$old,'to'=>$role]);return $d;}unset($x);throw new RuntimeException('ไม่พบ User');});$msg='เปลี่ยน Role ของ User แล้ว';
        } elseif($action==='set_super_admin'){
            $target=(int)($_POST['user_id']??0);$on=(int)($_POST['enabled']??0);
            db_mutate(function($d)use($target,$on,$u){$supers=array_values(array_filter($d['users'],fn($x)=>!empty($x['super_admin'])&&!empty($x['active'])));foreach($d['users'] as &$x){if((int)$x['id']!==$target)continue;if($on){$x['super_admin']=1;$x['role']='admin';}else{if(!empty($x['super_admin'])&&count($supers)<=1)throw new RuntimeException('ระบบต้องมี Super Admin อย่างน้อย 1 บัญชี');$x['super_admin']=0;}audit_permission($d,$u,'super_admin_changed',['user_id'=>$target,'enabled'=>$on]);return $d;}unset($x);throw new RuntimeException('ไม่พบ User');});$msg=$on?'มอบสิทธิ์ Super Admin แล้ว':'ถอดสิทธิ์ Super Admin แล้ว';
        } else throw new RuntimeException('Action ไม่ถูกต้อง');
    }catch(Throwable $e){$err=$e->getMessage();}
    $d=db_load();$canManage=user_can($u,'roles.manage',$d);
}
$roles=$d['roles']??[];$selectedRole=(string)($_GET['role']??array_key_first($roles));if(!isset($roles[$selectedRole]))$selectedRole=array_key_first($roles);
$targetUserId=(int)($_GET['user']??($d['users'][0]['id']??0));$targetUser=null;foreach($d['users'] as $x)if((int)$x['id']===$targetUserId){$targetUser=$x;break;}if(!$targetUser&&$d['users'])$targetUser=$d['users'][0];
function pc_count(array $r):int{return count(array_filter($r['permissions']??[]));}
