<div class="ambient"><i></i><i></i><i></i></div><?php require_once __DIR__.'/app/admin-nav.php'; echo admin_sidebar('access',$u); ?>
<main><header class="topbar"><button class="menu-btn" id="menuBtn">☰</button><div><p class="eyebrow">SECURITY / ACCESS CONTROL</p><h1>Role & Permission Center</h1><p>กำหนดสิทธิ์ระดับ Role + Override ราย User พร้อม Audit Log</p></div><div class="top-actions"><span class="access-badge"><?=user_is_super_admin($u)?'SUPER ADMIN':'PERMISSION ADMIN'?></span><a class="logout" href="admin.php">← Dashboard</a></div></header>
<?php if($msg):?><div class="notice ok">✓ <?=h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err">⚠ <?=h($err)?></div><?php endif;?>
<section class="permission-kpis"><article><small>Roles</small><b><?=count($roles)?></b><span>Built-in + Custom</span></article><article><small>Permissions</small><b><?=count($keys)?></b><span>ละเอียดระดับ Action</span></article><article><small>Users</small><b><?=count($d['users'])?></b><span>กำหนด Override ได้</span></article><article><small>Super Admin</small><b><?=count(array_filter($d['users'],fn($x)=>!empty($x['super_admin'])))?></b><span>Bypass ทุก Permission</span></article></section>
<div class="rbac-layout"><aside class="role-list panel"><div class="panel-head"><div><span class="step">R</span><h2>Roles</h2><p>เลือก Role เพื่อกำหนดสิทธิ์</p></div></div><?php foreach($roles as $rk=>$r):?><a href="?role=<?=urlencode($rk)?>" class="role-item <?=$selectedRole===$rk?'active':''?>"><div><b><?=h($r['name'])?></b><small><?=h($rk)?> · <?=pc_count($r)?> สิทธิ์</small></div><span><?=!empty($r['builtin'])?'SYSTEM':'CUSTOM'?></span></a><?php endforeach;?><?php if($canManage):?><form method="post" class="create-role"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create_role"><h3>+ Custom Role</h3><input name="name" placeholder="ชื่อ เช่น Manager" required><input name="slug" placeholder="role_key เช่น manager" required><input name="description" placeholder="คำอธิบาย"><select name="clone_role"><?php foreach($roles as $rk=>$r):?><option value="<?=h($rk)?>">คัดลอกจาก <?=h($r['name'])?></option><?php endforeach;?></select><button class="save-big">สร้าง Role</button></form><?php endif;?></aside>
<section class="panel permission-matrix"><div class="panel-head"><div><span class="step">P</span><h2><?=h($roles[$selectedRole]['name']??'Role')?> Permission Matrix</h2><p><?=h($roles[$selectedRole]['description']??'')?> · เลือกเฉพาะสิทธิ์ที่ Role นี้ควรทำได้</p></div><span class="matrix-count" id="permCount"><?=pc_count($roles[$selectedRole])?> / <?=count($keys)?></span></div><form method="post" id="roleForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_role"><input type="hidden" name="role" value="<?=h($selectedRole)?>"><div class="role-home"><label>หน้าแรกหลัง Login <select name="home"><option value="admin.php" <?=($roles[$selectedRole]['home']??'')==='admin.php'?'selected':''?>>Admin Dashboard</option><option value="dashboard.php" <?=($roles[$selectedRole]['home']??'')==='dashboard.php'?'selected':''?>>Staff Operations</option><option value="pr.php" <?=($roles[$selectedRole]['home']??'')==='pr.php'?'selected':''?>>PR Dashboard</option><option value="employee-time.php" <?=($roles[$selectedRole]['home']??'')==='employee-time.php'?'selected':''?>>Employee Time</option><option value="employee-calendar.php" <?=($roles[$selectedRole]['home']??'')==='employee-calendar.php'?'selected':''?>>Employee Calendar</option><option value="night-ops.php" <?=($roles[$selectedRole]['home']??'')==='night-ops.php'?'selected':''?>>Night Operations</option><option value="admin-tools.php" <?=($roles[$selectedRole]['home']??'')==='admin-tools.php'?'selected':''?>>Tools & Reports</option></select></label><small>กำหนด Landing Page ของ Role นี้</small></div><?php foreach($catalog as $gk=>$g):?><div class="perm-group"><div class="perm-group-head"><div><b><?=h($g['label'])?></b><small><?=count($g['items'])?> actions</small></div><label><input type="checkbox" class="group-toggle" data-group="<?=h($gk)?>" <?=$canManage?'':'disabled'?>> เลือกทั้งหมด</label></div><div class="perm-grid"><?php foreach($g['items'] as $pk=>$label):?><label class="perm-card"><input type="checkbox" name="perm[<?=h($pk)?>]" value="1" data-perm-group="<?=h($gk)?>" <?=!empty($roles[$selectedRole]['permissions'][$pk])?'checked':''?> <?=$canManage?'':'disabled'?>><span class="checkmark">✓</span><div><b><?=h($label)?></b><code><?=h($pk)?></code></div></label><?php endforeach;?></div></div><?php endforeach;?><div class="sticky-save"><div><b><?=!empty($roles[$selectedRole]['builtin'])?'Built-in Role':'Custom Role'?></b><small>การแก้ไขมีผลกับ User ที่ใช้ Role นี้ทันที</small></div><?php if($canManage):?><button class="save-big">บันทึก Permission</button><?php endif;?></div></form><?php if($canManage&&!empty($roles[$selectedRole])&&empty($roles[$selectedRole]['builtin'])):?><form method="post" onsubmit="return confirm('ยืนยันลบ Custom Role นี้?')" class="delete-role"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete_role"><input type="hidden" name="role" value="<?=h($selectedRole)?>"><button class="mini danger">ลบ Custom Role</button></form><?php endif;?></section></div>
<section class="panel wide user-access"><div class="panel-head"><div><span class="step">U</span><h2>User Access Override</h2><p>กำหนดสิทธิ์เฉพาะคน: ตาม Role / Allow / Deny</p></div></div><form method="get" class="user-picker"><input type="hidden" name="role" value="<?=h($selectedRole)?>"><select name="user" onchange="this.form.submit()"><?php foreach($d['users'] as $x):?><option value="<?=$x['id']?>" <?=((int)($targetUser['id']??0)===(int)$x['id'])?'selected':''?>><?=h($x['display_name'].' @'.$x['username'].' · '.$x['role'])?></option><?php endforeach;?></select></form><?php if($targetUser):?><div class="user-summary"><div class="avatar-big">👤</div><div><h3><?=h($targetUser['display_name'])?></h3><p>@<?=h($targetUser['username'])?> · Role: <b><?=h($roles[$targetUser['role']]['name']??$targetUser['role'])?></b></p></div><?php if(!empty($targetUser['super_admin'])):?><span class="super-pill">★ SUPER ADMIN</span><?php endif;?></div>
<?php if($canManage):?><div class="access-tools"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="set_user_role"><input type="hidden" name="user_id" value="<?=$targetUser['id']?>"><label>เปลี่ยน Role <select name="role"><?php foreach($roles as $rk=>$r):?><option value="<?=h($rk)?>" <?=$targetUser['role']===$rk?'selected':''?>><?=h($r['name'])?></option><?php endforeach;?></select></label><button class="mini secondary">บันทึก Role</button></form><form method="post" onsubmit="return confirm('ยืนยันเปลี่ยนสถานะ Super Admin?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="set_super_admin"><input type="hidden" name="user_id" value="<?=$targetUser['id']?>"><input type="hidden" name="enabled" value="<?=!empty($targetUser['super_admin'])?0:1?>"><button class="mini <?=!empty($targetUser['super_admin'])?'danger':'primary'?>"><?=!empty($targetUser['super_admin'])?'ถอด Super Admin':'ให้เป็น Super Admin'?></button></form></div><?php endif;?>
<form method="post" class="override-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_user_override"><input type="hidden" name="user_id" value="<?=$targetUser['id']?>"><?php foreach($catalog as $g):?><div class="override-group"><h3><?=h($g['label'])?></h3><?php foreach($g['items'] as $pk=>$label):$ov=$targetUser['permission_overrides'][$pk]??null;$effective=user_can($targetUser,$pk,$d);?><div class="override-row"><div><b><?=h($label)?></b><code><?=h($pk)?></code></div><span class="effective <?=$effective?'yes':'no'?>">Effective: <?=$effective?'ALLOW':'DENY'?></span><select name="override[<?=h($pk)?>]" <?=$canManage&&!user_is_super_admin($targetUser)?'':'disabled'?>><option value="inherit" <?=$ov===null?'selected':''?>>ตาม Role</option><option value="allow" <?=$ov===1||$ov==='1'?'selected':''?>>ALLOW เพิ่ม</option><option value="deny" <?=$ov===0||$ov==='0'?'selected':''?>>DENY เฉพาะคน</option></select></div><?php endforeach;?></div><?php endforeach;?><?php if($canManage&&!user_is_super_admin($targetUser)):?><div class="sticky-save"><div><b>User Override</b><small>Deny ราย User มีลำดับสูงกว่า Role</small></div><button class="save-big">บันทึก User Override</button></div><?php endif;?></form><?php endif;?></section>
<section class="panel wide"><div class="panel-head"><div><span class="step">A</span><h2>Permission Audit ล่าสุด</h2><p>ตรวจสอบว่าใครเปลี่ยนสิทธิ์อะไร เมื่อใด</p></div></div><div class="audit-list"><?php foreach(array_slice(array_reverse(array_values(array_filter($d['audit']??[],fn($a)=>str_contains((string)($a['action']??''),'role')||str_contains((string)($a['action']??''),'permission')||str_contains((string)($a['action']??''),'super_admin')))),0,20) as $a):?><div><span>◉</span><b><?=h((string)($a['action']??'-'))?></b><small><?=h(date('d/m/Y H:i:s',strtotime((string)$a['at'])))?> · by #<?=intval($a['by']??0)?></small></div><?php endforeach;?></div></section>
